import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/getisord/getisord_2022_gas.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['Gas_value'] = data['Gas_value'].fillna(data['Gas_value'].mean())

# Calculate the citywide average Gas value
citywide_average = data['Gas_value'].mean()

# Create a dictionary to store the total Gas value for each borough and its neighbors
total_gas_values = {}

# Function to get the neighbors of a borough
def get_neighbors(borough):
    return adjacency_data[adjacency_data['borough'] == borough]['neighbor'].tolist()

# Function to get the total Gas value for a borough and its neighbors
def get_total_gas_value(borough):
    total_value = data[data['borough'] == borough]['Gas_value'].values[0]
    neighbors = get_neighbors(borough)
    for neighbor in neighbors:
        total_value += data[data['borough'] == neighbor]['Gas_value'].values[0]
    return total_value

# Calculate the total Gas value for each borough and its neighbors
for index, row in data.iterrows():
    total_gas_values[row['borough']] = get_total_gas_value(row['borough'])

# Calculate the standard deviation of the total Gas values
std_dev = np.std(list(total_gas_values.values()))

# Calculate the z-score for each borough
z_scores = {}
for borough, total_value in total_gas_values.items():
    z_score = (total_value - citywide_average) / std_dev
    z_scores[borough] = z_score

# Identify hot and cold spots
hot_spots = {}
cold_spots = {}
for borough, z_score in z_scores.items():
    if z_score > 1.96:
        hot_spots[borough] = z_score
    elif z_score < -1.96:
        cold_spots[borough] = z_score

# Exclude boroughs with missing values
data_points_used = len(data) - data['Gas_value'].isnull().sum()

# Print the results
if hot_spots and cold_spots:
    results = []
    for borough in hot_spots:
        results.append(f"{borough} (HOT, Gi*={hot_spots[borough]}, gi_value={hot_spots[borough]})")
    for borough in cold_spots:
        results.append(f"{borough} (COLD, Gi*={cold_spots[borough]}, gi_value={cold_spots[borough]})")
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")

print(f"data_points_used = {data_points_used}")
